// ================= ATTENDANCE (Flow B) =================
function attendance() {
  const rows = PRIN.classes.map((c) => {
    const flow = c.c[0] === 'Diploma Y2 · Sec B';
    return { attrs: flow ? 'class="is-hl"' : '', cells: [`<b>${tt(c.c)}</b>`, c.teacher, flow ? `${when('att=due', '—', 'span')}${when('att=submitted|correction|corrected', n('55/60'), 'span')}` : c.p !== null ? n(`${c.p}/${c.t}`) : '—',
      flow ? `${when('att=due', st('due'), 'span')}${when('att=submitted', `${st('recorded')}<small>11:05</small>`, 'span')}${when('att=correction', `${st('pending')}<small>${t('Correction requested', 'সংশোধনের অনুরোধ')}</small>`, 'span')}${when('att=corrected', `${st('recorded')}<small>${t('Corrected 11:40', 'সংশোধিত ১১:৪০')}</small>`, 'span')}` : c.st === 'done' ? st('recorded') : st('missing'),
      flow ? when('att=correction', `<span class="f-acts">${btnAct(t('Approve correction', 'সংশোধন অনুমোদন'), { set: 'att=corrected', confirm: ['Approve the correction?', 'সংশোধন অনুমোদন করবেন?'], ctext: ['Roll 2405 changes from Absent to Leave (medical certificate).', 'রোল ২৪০৫ অনুপস্থিত থেকে ছুটিতে পরিবর্তিত হবে (মেডিকেল সনদ)।'], toast: ['Correction approved and logged.', 'সংশোধন অনুমোদিত ও লগ করা হয়েছে।'] }, 'btn-teal btn-sm')}</span>`, 'span') : c.st === 'missing' ? btnAct(t('Remind', 'মনে করান'), { set: '_=1', toast: ['Reminder sent.', 'রিমাইন্ডার পাঠানো হয়েছে।'] }, 'btn-outline btn-sm') : ''] };
  });
  const body = `${pageHead({ eyebrow: TODAY, title: t('Attendance', 'হাজিরা'), sub: t('Live student and teacher attendance. Teachers record attendance; the Principal approves corrections.', 'শিক্ষার্থী ও শিক্ষকের লাইভ হাজিরা। শিক্ষক হাজিরা নেন; অধ্যক্ষ সংশোধন অনুমোদন করেন।') })}
  ${when('att=submitted|correction|corrected', flowBanner('B', t('Diploma Y2 · Sec B recorded at 11:05 by Arif Hossain. District, division and Ministry views are updated.', 'আরিফ হোসেন ১১:০৫-এ ডিপ্লোমা ২য় বর্ষ · সেকশন বি-এর হাজিরা লিপিবদ্ধ করেছেন। জেলা, বিভাগ ও মন্ত্রণালয়ের দৃশ্য হালনাগাদ হয়েছে।'), a('district.html', t('District view', 'জেলার দৃশ্য'), 'btn btn-outline btn-sm')))}
  ${kpis([{ l: ['Students present', 'উপস্থিত শিক্ষার্থী'], raw: `${when('att=due', n('72.4%'), 'span')}${when('att=submitted|correction|corrected', n('76.9%'), 'span')}`, s: ['Threshold 80%', 'সীমা ৮০%'], tone: 'danger' }, { l: ['Teachers present', 'উপস্থিত শিক্ষক'], v: '46 / 48', s: ['2 on approved leave', '২ জন অনুমোদিত ছুটিতে'] }, { l: ['Classes recorded', 'লিপিবদ্ধ ক্লাস'], raw: `${when('att=due', n('4 / 6'), 'span')}${when('att=submitted|correction|corrected', n('5 / 6'), 'span')}`, s: ['Today', 'আজ'] }])}
  ${tabs('ia', [
    { id: 'students', l: ['Students by class', 'ক্লাসভিত্তিক শিক্ষার্থী'], content: table({ id: 'ia-tbl', cols: [{ l: ['Class', 'ক্লাস'] }, { l: ['Teacher', 'শিক্ষক'] }, { l: ['Present', 'উপস্থিত'], cls: 'num' }, { l: ['Status', 'অবস্থা'] }, { l: ['Action', 'কাজ'] }], rows }) },
    { id: 'teachers', l: ['Teachers', 'শিক্ষক'], content: table({ id: 'ia-t', compact: true, cols: [{ l: ['Teacher', 'শিক্ষক'] }, { l: ['Check-in', 'উপস্থিতি'] }, { l: ['Status', 'অবস্থা'] }], rows: [['Arif Hossain', '08:52', 'recorded'], ['Nusrat Jahan', '08:47', 'recorded'], ['Tahmina Akter', '09:41', 'late'], ['Kamrul Hasan', '—', 'approved']].map((r) => ({ cells: [r[0], n(r[1]), r[3] === 'approved' ? `<span class="tag tag-neutral">${t('On leave (approved)', 'ছুটিতে (অনুমোদিত)')}</span>` : st(r[2])] })) }) },
  ])}
  <p class="f-chart-meta">${t('Teacher attendance capture method (device / app / manual)', 'শিক্ষক হাজিরা গ্রহণের পদ্ধতি (ডিভাইস / অ্যাপ / ম্যানুয়াল)')} — ${tbd()}</p>`;
  return P('inst-attendance', ['Attendance', 'হাজিরা'], [['Attendance', 'হাজিরা']], body);
}

