function access() {
  const roles = [['Teacher', 'শিক্ষক'], ['Accountant', 'হিসাবরক্ষক'], ['Librarian', 'লাইব্রেরিয়ান'], ['Store keeper', 'স্টোর কিপার']];
  const mods = [['Attendance', 'হাজিরা', [1, 0, 0, 0]], ['Results entry', 'ফলাফল এন্ট্রি', [1, 0, 0, 0]], ['Class materials', 'ক্লাসের উপকরণ', [1, 0, 0, 0]], ['Finance', 'অর্থ', [0, 1, 0, 0]], ['Library', 'লাইব্রেরি', [0, 0, 1, 0]], ['Assets & procurement', 'সম্পদ ও ক্রয়', [0, 0, 0, 1]], ['Student requests (view)', 'শিক্ষার্থীর আবেদন (দেখা)', [0, 1, 0, 0]]];
  const body = `${pageHead({ title: t('Menu access', 'মেনু অ্যাক্সেস'), sub: t('Choose which menus each institution role can see. Changes apply at next sign-in.', 'প্রতিষ্ঠানের প্রতিটি ভূমিকা কোন মেনু দেখবে তা নির্বাচন করুন। পরবর্তী লগইনে পরিবর্তন কার্যকর হবে।') })}
  <div class="f-table-wrap"><table class="f-table f-matrix"><thead><tr><th>${t('Menu', 'মেনু')}</th>${each(roles, (r) => `<th>${tt(r)}</th>`)}</tr></thead><tbody>${each(mods, ([e, b, v]) => `<tr><td>${t(e, b)}</td>${v.map((x, i) => `<td><input type="checkbox" ${x ? 'checked' : ''} aria-label="${e} — ${roles[i][0]}"></td>`).join('')}</tr>`)}</tbody></table></div>
  <div class="f-btnrow">${btnAct(t('Save menu access', 'মেনু অ্যাক্সেস সংরক্ষণ'), { set: '_=1', toast: ['Menu access saved.', 'মেনু অ্যাক্সেস সংরক্ষিত।'] })}</div>
  <p class="f-chart-meta">${t('Ministry-defined permissions are the upper limit; the Principal can only narrow them.', 'মন্ত্রণালয়-নির্ধারিত অনুমতি সর্বোচ্চ সীমা; অধ্যক্ষ শুধু তা সীমিত করতে পারেন।')}</p>`;
  return P('inst-access', ['Menu access', 'মেনু অ্যাক্সেস'], [['Menu access', 'মেনু অ্যাক্সেস']], body);
}

